recipes.command:
mkdir -p bots/discord_bot && cd bots/discord_bot && npm init -y && npm install discord.js dotenv && cat << 'FEOF' > index.js
import { Client, GatewayIntentBits } from 'discord.js';
const client = new Client({ intents: [GatewayIntentBits.Guilds] });
client.once('ready', () => console.log('VERY SYSTEMS Bot Online!'));
client.login(process.env.DISCORD_TOKEN);
FEOF
echo 'Bot Discord criado com sucesso!'
